              return util::f32_to_f16_ovfl_simd(amdgpu::transcendental::log_exp_f16_simd<false>(
                  util::f16_to_f32_simd(a), wf.fp_denorm_mode_f16_f64(), wf.fp16_ovfl(),
                  amdgpu::fp_mode::quiets_nan(wf.cu().arch(), wf.ieee_mode())));
